a = float(input('First number: '))
b = float(input('Second number: '))
op = input('Operation (+, -, *, /): ')

if op == '+':
    print(a + b)
elif op == '-':
    print(a - b)
elif op == '*':
    print(a * b)
elif op == '/':
    if b == 0:
        print('Cannot divide by zero')
    else:
        print(a / b)
else:
    print('Unknown operation')

def calculate(a, b, op):
    if op == '+':
        return a + b
    elif op == '-':
        return a - b
    elif op == '*':
        return a * b
    elif op == '/':
        if b == 0:
            return 'Cannot divide by zero'
        return a / b
    else:
        return 'Unknown operation'

print(calculate(10, 4, '+'))

