def calculate(a, b, op):
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        return a / b if b != 0 else 'Cannot divide by zero'
    return 'Unknown operation'

print(calculate(10, 4, '+'))
